import { extraExercises } from './more-exercises.ts'

export type CategoryId = 'foundation' | 'nouns' | 'verbs' | 'modals' | 'sentences' | 'modifiers' | 'clauses' | 'transformations' | 'advanced'

export type Exercise =
  | { type: 'choice'; prompt: string; options: string[]; answer: number; explanation: string }
  | { type: 'fill'; prompt: string; answers: string[]; explanation: string }
  | { type: 'order'; prompt: string; words: string[]; answer: string; explanation: string }

export type Lesson = {
  id: string
  category: CategoryId
  title: string
  subtitle: string
  prerequisites: string[]
  structure: string
  overview: string
  uses: string[]
  examples: [string, string][]
  contrast: string
  mistake: string
  summary: string
  exercises: Exercise[]
}

export const categories: { id: CategoryId; name: string; description: string; symbol: string }[] = [
  { id: 'foundation', name: 'Nền tảng câu', description: 'Hiểu từ, cụm từ và cách dựng một câu rõ nghĩa.', symbol: 'Aa' },
  { id: 'nouns', name: 'Danh từ & đại từ', description: 'Gọi tên, xác định và thay thế người hay vật.', symbol: 'N' },
  { id: 'verbs', name: 'Động từ & thời gian', description: 'Diễn tả hành động, trạng thái và góc nhìn về thời gian.', symbol: 'V' },
  { id: 'modals', name: 'Động từ khuyết thiếu', description: 'Nói về khả năng, nghĩa vụ, suy đoán và lời khuyên.', symbol: 'M' },
  { id: 'sentences', name: 'Kiểu câu', description: 'Đặt câu hỏi, phủ định, yêu cầu và nhấn mạnh.', symbol: '?' },
  { id: 'modifiers', name: 'Bổ nghĩa & quan hệ', description: 'Miêu tả, so sánh và đặt sự việc trong bối cảnh.', symbol: '↗' },
  { id: 'clauses', name: 'Mệnh đề & câu phức', description: 'Nối ý, nêu điều kiện và tạo câu nhiều tầng nghĩa.', symbol: '§' },
  { id: 'transformations', name: 'Chuyển đổi câu', description: 'Đổi góc nhìn bằng bị động, tường thuật và cấu trúc khác.', symbol: '⇄' },
  { id: 'advanced', name: 'Sắc thái nâng cao', description: 'Viết và nói chính xác, tự nhiên theo mục đích.', symbol: '✦' },
]

const choice = (prompt: string, options: string[], answer: number, explanation: string): Exercise => ({ type: 'choice', prompt, options, answer, explanation })
const fill = (prompt: string, answers: string[], explanation: string): Exercise => ({ type: 'fill', prompt, answers, explanation })
const order = (prompt: string, words: string[], answer: string, explanation: string): Exercise => ({ type: 'order', prompt, words, answer, explanation })

