export const lessons: Lesson[] = baseLessons.map((lesson) => ({
  ...lesson,
  exercises: [...lesson.exercises, ...(extraExercises[lesson.id] ?? [])],
}))

export const lessonById: Record<string, Lesson> = Object.fromEntries(lessons.map((lesson) => [lesson.id, lesson]))

export type RoadmapStage = { id: string; title: string; subtitle: string; lessonIds: string[] }

export const roadmap: RoadmapStage[] = [
  { id: 'start', title: 'Nền tảng câu', subtitle: 'Nhận ra các khối xây dựng một câu và diễn đạt ý đơn giản.', lessonIds: ['word-classes', 'sentence-parts', 'phrases-clauses', 'basic-word-order', 'be-have-do', 'there-and-it', 'pronouns', 'nouns-countability', 'plural-nouns', 'articles', 'agreement'] },
  { id: 'time', title: 'Diễn đạt thời gian & sự việc', subtitle: 'Kể thói quen, việc đang diễn ra, chuyện đã qua và dự định.', lessonIds: ['present-simple', 'present-continuous', 'past-simple', 'past-continuous', 'past-habits', 'future-forms', 'present-perfect-form', 'present-perfect-vs-past', 'stative-verbs', 'past-perfect', 'present-perfect-continuous', 'future-continuous-perfect'] },
  { id: 'expand', title: 'Mở rộng câu', subtitle: 'Thêm lượng, đặc điểm, quan hệ và mức độ chính xác.', lessonIds: ['articles-special', 'determiners', 'possessives', 'quantifiers', 'each-every-either', 'noun-phrases', 'verb-complements', 'adjectives-adverbs', 'comparison', 'adverb-position', 'prepositions-time-place', 'preposition-patterns', 'phrasal-verbs', 'gerund-infinitive', 'modal-ability', 'modal-obligation', 'modal-deduction', 'negation', 'questions', 'imperatives'] },
  { id: 'connect', title: 'Kết nối ý', subtitle: 'Diễn tả nguyên nhân, điều kiện, bổ sung thông tin và lập luận.', lessonIds: ['conjunctions', 'adverbial-clauses', 'relative-clauses', 'relative-clauses-advanced', 'noun-clauses', 'conditionals-basic', 'conditionals-unreal', 'linking-ideas', 'question-tags', 'reported-speech'] },
  { id: 'structure', title: 'Cấu trúc nâng cao', subtitle: 'Đổi góc nhìn, rút gọn và nhấn mạnh đúng trọng tâm.', lessonIds: ['passive', 'passive-advanced', 'causative', 'participle-clauses', 'modal-perfect', 'emphasis', 'inversion', 'wish-subjunctive', 'cleft-sentences'] },
  { id: 'nuance', title: 'Sắc thái & văn phong', subtitle: 'Viết gọn, thận trọng và mạch lạc theo từng ngữ cảnh.', lessonIds: ['nominalisation', 'ellipsis-substitution', 'hedging-register', 'punctuation', 'linking-ideas', 'articles', 'conditionals-unreal'] },
]

export function validateContent(): string[] {
  const errors: string[] = []
  const ids = new Set<string>()
  const categoryIds = new Set(categories.map((category) => category.id))
  for (const lesson of lessons) {
    if (ids.has(lesson.id)) errors.push(`Trùng mã bài: ${lesson.id}`)
    ids.add(lesson.id)
    if (!categoryIds.has(lesson.category)) errors.push(`Nhóm không tồn tại: ${lesson.id}`)
    if (!lesson.overview || !lesson.structure || lesson.uses.length < 2 || lesson.examples.length < 2 || !lesson.contrast || !lesson.mistake || !lesson.summary) errors.push(`Nội dung chưa hoàn chỉnh: ${lesson.id}`)
    if (lesson.exercises.length < 3) errors.push(`Cần ít nhất ba bài tập: ${lesson.id}`)
    for (const exercise of lesson.exercises) {
      if (!exercise.prompt || !exercise.explanation) errors.push(`Bài tập chưa hoàn chỉnh: ${lesson.id}`)
      if (exercise.type === 'choice' && (exercise.options.length < 2 || !Number.isInteger(exercise.answer) || exercise.answer < 0 || exercise.answer >= exercise.options.length || exercise.options.some((option) => !option.trim()) || new Set(exercise.options).size !== exercise.options.length)) errors.push(`Đáp án trắc nghiệm không hợp lệ: ${lesson.id}`)
      if (exercise.type === 'fill' && (exercise.answers.length === 0 || exercise.answers.some((answer) => !answer.trim()))) errors.push(`Thiếu đáp án điền từ: ${lesson.id}`)
      if (exercise.type === 'order') {
        const tokens = (value: string) => value.toLowerCase().replace(/[.!?]/g, '').split(/\s+/).sort().join(' ')
        if (exercise.words.length === 0 || exercise.words.some((word) => !word.trim()) || tokens(exercise.words.join(' ')) !== tokens(exercise.answer)) errors.push(`Đáp án sắp xếp không hợp lệ: ${lesson.id}`)
      }
    }
  }
  for (const lesson of lessons) {
    for (const prerequisite of lesson.prerequisites) if (!ids.has(prerequisite) || prerequisite === lesson.id) errors.push(`Liên kết tiên quyết hỏng: ${lesson.id} → ${prerequisite}`)
  }
  const referenced = new Set<string>()
  for (const stage of roadmap) {
    if (new Set(stage.lessonIds).size !== stage.lessonIds.length) errors.push(`Bài lặp trong chặng: ${stage.id}`)
    for (const id of stage.lessonIds) {
      referenced.add(id)
      if (!ids.has(id)) errors.push(`Roadmap trỏ tới bài không tồn tại: ${stage.id} → ${id}`)
    }
  }
  for (const id of ids) if (!referenced.has(id)) errors.push(`Bài chưa có trong roadmap: ${id}`)
  for (const id of Object.keys(extraExercises)) if (!ids.has(id)) errors.push(`Bài tập trỏ tới bài không tồn tại: ${id}`)
  return errors
}
